        cmdStr("VH[2]", r.vh2),
        cmdStr("ER[3]", r.er3),
        cmdStr("ER[2]", r.er2),
        cmdStr("TR[1]", r.tr1),
        cmdStr("TR[3]", r.tr3),
        cmdStr("TR[2]", r.tr2 != null ? r.tr2 : 100),
        cmdStr("TR[4]", r.tr4 != null ? r.tr4 : 100),
    ];
}

// Единственный источник предельной скорости — VH[2] привода для пары головок (Замечания п. 6).
// Кастомные диапазоны и допуск из настроек убраны. Скорость может быть отрицательной
// (обратное вращение), поэтому всё сравнивается по модулю; нижнего предела нет (0 — остановка).
// Привод отдаёт VH[2] только активной пары, поэтому прочитанные значения копятся в
// global.drive_vh2_ticks; до первого чтения берётся номинал из таблицы RES.
function driveVh2Ticks(resKey) {
    var base = RES[resKey] || RES.high;
    var map = global.get("drive_vh2_ticks") || {};
    var live = Number(map[resKey]);
    if (isFinite(live) && live > 0) return Math.round(live);
    return Math.round(base.vh2);
}

function ticksPerDegByRes(resKey) {
    var r = RES[resKey] || RES.high;
    return r.ca18 / 360;
}

function degPerSecToTicksByRes(degPerSec, resKey) {
    return Math.round((Number(degPerSec) || 0) * ticksPerDegByRes(resKey));
}

// Таймаут ожидания завершения оборота поиска нулевой метки. После захвата метки привод
// сбрасывает счётчик (HM[5]=0), и относительная цель PR «уезжает» — ось может сделать
// до одного лишнего оборота (Рекомендации, разд. 6), поэтому бюджет = 2 оборота + разгон + запас.
function initMotionTimeoutMs(turns, speedDegSec, accelDegSec2) {
    var distanceDeg = Math.max(1, (Math.abs(Number(turns) || 1) + 1) * 360);
    var speed = Math.max(0.001, Math.abs(Number(speedDegSec) || 5));
    var accel = Math.max(0.001, Math.abs(Number(accelDegSec2) || 1));
    var rampSec = speed / accel;
    var travelSec = distanceDeg / speed + 2 * rampSec;
    return Math.max(60000, Math.ceil((travelSec + 30) * 1000));
}

// Минимальное время, раньше которого MS=0 не считается завершением оборота
// (сразу после BG привод может ещё отдавать MS=0 предыдущей команды).
function initMinMotionMs(speedDegSec, accelDegSec2) {
    var speed = Math.max(0.001, Math.abs(Number(speedDegSec) || 5));
    var accel = Math.max(0.001, Math.abs(Number(accelDegSec2) || 1));
    return Math.ceil((speed / accel + 1) * 1000);
}

function homingMotionSettings() {
    var settings = global.get("settings") || {};
    var advanced = settings.advanced || {};
    var speed = Number(advanced.homingSpeedDegSec);
    var accel = Number(advanced.homingAccelDegSec2);
    return {
        speedDegSec: isFinite(speed) && speed > 0 ? speed : 5,
        accelDegSec2: isFinite(accel) && accel > 0 ? accel : 1,
    };
}

// Окна/выдержки MS (TR[1..4]) из настроек в тиках текущей пары головок (Б1.2).
function configuredTrWindows(resKey, base) {
    var settings = global.get("settings") || {};
    var advanced = settings.advanced || {};
    var w = (advanced.trWindows && advanced.trWindows[resKey]) || {};
    var tpd = ticksPerDegByRes(resKey);
    var posDeg = Number(w.positionWindowDeg);
    var spdDeg = Number(w.speedWindowDegSec);
    var posMs = Math.round(Number(w.positionTimeMs));
    var spdMs = Math.round(Number(w.speedTimeMs));
    return {
        tr1: isFinite(posDeg) && posDeg > 0 ? Math.max(1, Math.round(posDeg * tpd)) : base.tr1,
        tr3: isFinite(spdDeg) && spdDeg > 0 ? Math.max(1, Math.round(spdDeg * tpd)) : base.tr3,
        tr2: isFinite(posMs) && posMs >= 1 ? posMs : (base.tr2 != null ? base.tr2 : 100),
        tr4: isFinite(spdMs) && spdMs >= 1 ? spdMs : (base.tr4 != null ? base.tr4 : 100),
    };
}

function trWindowCmds(r) {
    return [
        cmdStr("TR[1]", r.tr1),
        cmdStr("TR[2]", r.tr2),
        cmdStr("TR[3]", r.tr3),
        cmdStr("TR[4]", r.tr4),
    ];
}

function initVelocityToleranceTicks(resKey) {
    return Math.max(1, Math.round(ticksPerDegByRes(resKey) * 0.01));
}

function effectiveResParams(resKey) {
    var base = RES[resKey] || RES.high;
    var r = Object.assign({}, base);
    r.vh2 = driveVh2Ticks(resKey);
    Object.assign(r, configuredTrWindows(resKey, base));
    return r;
}

function buildDriveLimits(resKey) {
    var r = effectiveResParams(resKey);
    var ticksPerDeg = ticksPerDegByRes(resKey);
    var speedMaxTicks = Math.round(r.vh2);
    var accelMaxTicks = Math.min(Math.round(r.sd), Math.round(r.vh1), Math.round(r.vl1));
    return {
        resolution: resKey,
        ticks_per_deg: ticksPerDeg,
        speed_min_deg: 0,
        speed_max_deg: speedMaxTicks / ticksPerDeg,
        speed_min_ticks: 0,
        speed_max_ticks: speedMaxTicks,
        drive_vh2_ticks: speedMaxTicks,
        speed_min_validate_ticks: 0,
        speed_max_validate_ticks: speedMaxTicks,
        accel_min_ticks: 0,
        accel_max_ticks: accelMaxTicks,
        accel_max_deg: accelMaxTicks / ticksPerDeg,
        decel_min_ticks: 0,
        decel_max_ticks: accelMaxTicks,
        decel_max_deg: accelMaxTicks / ticksPerDeg,
    };
}

function syncDriveLimits(resKey) {
    var limits = buildDriveLimits(resKey);
    flow.set("drive_limits", limits);
    global.set("drive_limits", limits);
    global.set("current_range", resKey);
    return limits;
}

function clampTicks(value, min, max) {
    var n = Math.round(Number(value) || 0);
    var lo = Math.round(Number(min) || 0);
    var hi = Math.round(Number(max) || 0);
    if (hi < lo) hi = lo;
    if (n < lo) return lo;
    if (n > hi) return hi;
    return n;
}

function preserveMotionParamsForResolution(params, oldLimits, newLimits, oldResKey) {
    params = params || {};
    var oldTicksPerDeg = Number(oldLimits && oldLimits.ticks_per_deg) || ticksPerDegByRes(oldResKey);
    var newTicksPerDeg = Number(newLimits && newLimits.ticks_per_deg) || ticksPerDegByRes(newLimits && newLimits.resolution);
    var oldSpDeg = Math.abs((Number(params.sp) || 0) / oldTicksPerDeg);
    var oldAcDeg = Math.abs((Number(params.ac) || 0) / oldTicksPerDeg);
    var oldDcDeg = Math.abs((Number(params.dc) || 0) / oldTicksPerDeg);
    var spTicks = oldSpDeg === 0 ? 0 : Math.round(oldSpDeg * newTicksPerDeg);
    if (spTicks !== 0) {
        spTicks = clampTicks(spTicks, 0, newLimits.speed_max_ticks);
    }
    return {
        sp: spTicks,
        ac: clampTicks(Math.round(oldAcDeg * newTicksPerDeg), newLimits.accel_min_ticks, newLimits.accel_max_ticks),
        dc: clampTicks(Math.round(oldDcDeg * newTicksPerDeg), newLimits.decel_min_ticks, newLimits.decel_max_ticks),
    };
}

function validateUnsignedSpeed(name, value, limits, allowZero) {
    var n = Math.round(Number(value) || 0);
    if (n === 0 && allowZero) { return { ok: true, value: 0 }; }
    if (n < 0) { node.warn(name + ": speed cannot be negative"); return { ok: false }; }
    return validateSpeedMagnitude(name, n, limits);
}

function validateSignedSpeed(name, value, limits, allowZero) {
    var n = Math.round(Number(value) || 0);
    if (n === 0 && allowZero) { return { ok: true, value: 0 }; }
    return validateSpeedMagnitude(name, n, limits);
}

// Единственная проверка скорости: |v| <= VH[2] пары головок. Привод всё равно обрежет большее
// значение, поэтому ПО отклоняет его явно, с сообщением (Замечания п. 6, Б1.6 / Б4.8).
function validateSpeedMagnitude(name, ticks, limits) {
    var abs = Math.abs(ticks);
    var maxTicks = Math.round(Number(limits.speed_max_ticks) || 0);
    if (maxTicks > 0 && abs > maxTicks) {
        node.warn(name + ": value " + ticks + " ticks/s exceeds VH[2] = " + maxTicks + " ticks/s ("
            + (maxTicks / (limits.ticks_per_deg || 1)).toFixed(3) + " deg/s) for resolution " + limits.resolution);
        return { ok: false };
    }
    return { ok: true, value: ticks };
}

function validateAccel(name, value, minTicks, maxTicks) {
    var n = Math.round(Number(value) || 0);
    if (n < minTicks || n > maxTicks) {
        node.warn(name + ": значение " + n + " тик/с² вне допустимого диапазона [" + minTicks + ".." + maxTicks + "]");
        return { ok: false };
    }
    return { ok: true, value: n };
}

// ──────────────────────────────────────────────────────────────────────────
// Константы разрешений (мануал, раздел 4, таблица 4.1)
// ──────────────────────────────────────────────────────────────────────────

var RES = {
    high: {
        ol1: 0,
        ca18: 262144000,
        s1_5: 40,
        kp2: 5e-7,
        sd: 131072000,   // 180 °/с²
        qs: 131072000,
        vh1: 131072000,
        vl1: 131072000,
        vh2: 34952533,     // physical high-head ceiling ~48 deg/s; clamped to settings range by effectiveResParams
        er3: 131072000,   // окно ошибки позиции 180°
        er2: 131072000,   // окно ошибки скорости
        tr1: 7282,        // окно позиции 0.01°
        tr3: 364089,      // окно скорости 0.5°/с
        tr2: 100,         // выдержка в окне позиции мс (нельзя 0 — шумит MS)
        tr4: 100,         // выдержка в окне скорости мс
        sp_def: 728177,      // 1 °/с
        ac_def: 364088,      // 0.5 °/с²
    },
    low: {
        ol1: 1,
        ca18: 6553600,
        s1_5: 40,
        kp2: 1e-5,
        sd: 3276800,     // 180 °/с²
        qs: 3276800,
        vh1: 3276800,
        vl1: 3276800,
        vh2: 6553600,     // макс. скорость
        er3: 3276800,
        er2: 3276800,
        tr1: 182,         // окно позиции 0.01°
        tr3: 9102,        // окно скорости 0.5°/с
        tr2: 100,
        tr4: 100,
        sp_def: 18204,       // 1 °/с
        ac_def: 9102,        // 0.5 °/с²
    },
};

// ──────────────────────────────────────────────────────────────────────────
// Текущее разрешение и параметры движения из flow context
// ──────────────────────────────────────────────────────────────────────────

var driveState = global.get("drive_state") || {};
var pollState = flow.get("poll_buffer") || {};
var contextRes = driveState.resolution || pollState.resolution || global.get("current_range") || flow.get("resolution") || "high";
var currentRes = RES[contextRes] ? contextRes : "high";
var resParams = effectiveResParams(currentRes);
var currentLimits = syncDriveLimits(currentRes);

var storedParams = flow.get("motion_params") || {
    sp: resParams.sp_def,
    ac: resParams.ac_def,
    dc: resParams.ac_def,
};

// ──────────────────────────────────────────────────────────────────────────
// Маршрутизация
// ──────────────────────────────────────────────────────────────────────────

var payload = msg.payload;
var elmoCmd = null;
var elmoMeta = {};
var verifyMotionStart = payload && payload.verifyMotionStart === true;
// A stop or a newer search supersedes delayed setup stages of a scenario search.
if (["driveInit", "drive_init", "motor_off", "drive_stop", "homing_stop"].includes(topic)) {
    context.set("initSequence", (context.get("initSequence") || 0) + 1);
}

switch (topic) {

    // ────────────────────────────────────────────────────────────────────
    // "reread" — опрос текущего состояния привода
    // Добавлен OL[1] для чтения текущего разрешения головок ДУ
    // ────────────────────────────────────────────────────────────────────
    case "reread":
        elmoCmd = joinCmds(
            "OL[1]",
            "TR[1]",
            "TR[2]",
            "TR[3]",
            "TR[4]",
            "AF",
            "SR",
            "MO",
            "SO",
            "PX",
            "VX",
            "SP",
            "AC",
            "DC",
            "JV",
            "JP",
            "SD",
            "QS",
            "VH[1]",
            "VL[1]",
            "VH[2]",
        "KP[2]"
        );
        break;

    // ────────────────────────────────────────────────────────────────────
    // "set_motion_params" — задать SP, AC, DC
    // payload: { sp_ticks, ac_ticks, dc_ticks, jerk_ticks (опц.) }
    // jerk_ticks игнорируется (Elmo не имеет команды jerk напрямую)
    // ────────────────────────────────────────────────────────────────────
    case "set_motion_params":
        if (!payload) { node.warn("set_motion_params: нет payload"); return null; }

        var sp = Math.round(payload.sp_ticks !== undefined ? payload.sp_ticks : resParams.sp_def);
        var ac = Math.round(payload.ac_ticks !== undefined ? payload.ac_ticks : resParams.ac_def);
        var dc = Math.round(payload.dc_ticks !== undefined ? payload.dc_ticks : resParams.ac_def);
        var spCheck = validateUnsignedSpeed("set_motion_params/SP", sp, currentLimits, true);
        var acCheck = validateAccel("set_motion_params/AC", ac, currentLimits.accel_min_ticks, currentLimits.accel_max_ticks);
        var dcCheck = validateAccel("set_motion_params/DC", dc, currentLimits.decel_min_ticks, currentLimits.decel_max_ticks);
        if (!spCheck.ok || !acCheck.ok || !dcCheck.ok) return null;

        sp = spCheck.value;
        ac = acCheck.value;
        dc = dcCheck.value;

        flow.set("motion_params", { sp: sp, ac: ac, dc: dc });

        elmoCmd = joinCmds(
            cmdStr("SP", sp),
            cmdStr("AC", ac),
            cmdStr("DC", dc),
            "SP",
            "AC",
            "DC"
        );
        break;

    // ────────────────────────────────────────────────────────────────────
    // "motor_on" — включение привода
    // Мануал раздел 3: перед MO=1 биты SR[0-3] должны быть 0
    // ────────────────────────────────────────────────────────────────────
    case "motor_on":
        // ST перед MO=1 сбрасывает незавершённую команду движения, чтобы включение
        // двигателя не подхватило старый профиль (Замечания п. 13 / Б1.7). BG здесь не шлём.
        elmoCmd = joinCmds("ST", "MO=1", "MO", "SO", "SR");
        break;

    // ────────────────────────────────────────────────────────────────────
    // "motor_off" — выключение привода
    // ────────────────────────────────────────────────────────────────────
    case "motor_off":
        elmoCmd = joinCmds("MO=0", "MO", "SO", "SR");
        break;

    // ────────────────────────────────────────────────────────────────────
    // "drive_stop" — быстрая остановка с замедлением QS
    // ────────────────────────────────────────────────────────────────────
    case "drive_stop":
        elmoCmd = "ST";
        break;

    // ────────────────────────────────────────────────────────────────────
    // "drive_bg" — запуск последней заданной команды (PA/PR/JV/JP)
    // ────────────────────────────────────────────────────────────────────

    // ────────────────────────────────────────────────────────────────────
    // "set_kp2" — записать KP[2] в привод ELMO
    // payload: { kp2: <number> }  (не сохраняется в файл)
    // ────────────────────────────────────────────────────────────────────
    case "set_kp2":
        if (!payload || payload.kp2 === undefined || payload.kp2 === null) {
            node.warn("set_kp2: no kp2 in payload");
            return null;
        }
        var kp2Set = Number(payload.kp2);
        if (!isFinite(kp2Set)) { node.warn("set_kp2: invalid kp2 value: " + payload.kp2); return null; }
        elmoCmd = cmdStr("KP[2]", kp2Set);
        break;

    case "drive_bg":
        elmoCmd = "BG";
        break;

    // ────────────────────────────────────────────────────────────────────
    // "homing_stop" — остановка оси сразу после захвата нулевой метки
    // (Рекомендации, разд. 6, шаг 6: иначе ось делает лишний оборот).
    // Шлёт DriveInitState при смене бита HM[1] в SR 1→0. ST в транспорте
    // прерывает ожидание оборота (CMD.FAILED operator_aborted) — DriveInitState
    // трактует это как успешное завершение. Затем читаем HM[7] (смещение) и PX.
    // ────────────────────────────────────────────────────────────────────
    case "homing_stop":
        elmoCmd = joinCmds("ST", "HM[7]", "PX", "MS");
        break;

    // ────────────────────────────────────────────────────────────────────
    // "apply_tr_windows" — записать окна/выдержки MS (TR[1..4]) из настроек
    // для текущей пары головок и прочитать их обратно для контроля (Б1.2).
    // Приходит из SettingsNormalize после каждого сохранения настроек.
    // ────────────────────────────────────────────────────────────────────
    // "apply_vh2" — записать VH[2] активной пары (введено на вкладке «Настройка») и прочитать обратно
    case "apply_vh2":
        var vh2Ticks = Math.round(Number(effectiveResParams(currentRes).vh2));
        if (!(isFinite(vh2Ticks) && vh2Ticks > 0)) { node.warn("apply_vh2: нет значения VH[2] для " + currentRes); return null; }
        elmoCmd = joinCmds(cmdStr("VH[2]", vh2Ticks), "VH[2]");
        node.log("apply_vh2 (" + currentRes + ") VH[2]=" + vh2Ticks);
        break;

    case "apply_tr_windows":
        var trRes = effectiveResParams(currentRes);
        elmoCmd = joinCmds(trWindowCmds(trRes).concat(["TR[1]", "TR[2]", "TR[3]", "TR[4]"]));
        node.log("apply_tr_windows (" + currentRes + ") TR[1]=" + trRes.tr1 + " TR[2]=" + trRes.tr2 + " TR[3]=" + trRes.tr3 + " TR[4]=" + trRes.tr4);
        break;

    // ────────────────────────────────────────────────────────────────────
    // "driveInit" — поиск нулевой метки (homing) по Рекомендациям, разд. 6.
    //
    //   1. HM[3]=3, HM[4]=2, HM[5]=0; HM[1]=0 (сброс незавершённого поиска),
    //      затем HM[1]=1 — бит 7 SR становится 1.
    //   2. Поворот ровно на один оборот PR=CA[18] (скорость/ускорение из
    //      настроек: homingSpeedDegSec / homingAccelDegSec2, по умолчанию
    //      5 °/с и 1 °/с²). Во время оборота транспорт опрашивает MS/PX/SR;
    //      смена бита 7 SR 1→0 — метка найдена (фиксирует DriveInitState).
    //   3. Завершение — по MS (motion done), без привязки к абсолютной цели
    //      PX: после захвата метки счётчик сбрасывается (HM[5]=0), и цель
    //      PR «уезжает», поэтому старый критерий «PX == base+1 оборот»
    //      давал ложную ошибку по таймауту.
    //
    // payload опционален:
    //   { resolution: "high" | "low", mode: "manual" | "full" | "scenario" }
    //   manual — двигатель уже включён, только HM + оборот;
    //   full/scenario — ST, MO=0, параметры пары головок, PX=0, MO=1, HM + оборот.
    // ────────────────────────────────────────────────────────────────────
    case "driveInit":
    case "drive_init":
        var initRes = RES[currentRes] ? currentRes : "high";
        var initPayload = payload && typeof payload === "object" ? payload : {};
        if (initPayload.resolution) {
            initRes = (initPayload.resolution === "low") ? "low" : "high";
        }
        var initMode = initPayload.mode || (initPayload.full === true || initPayload.autoRangeSwitch === true ? "full" : "manual");
        var fullInit = initMode === "full" || initMode === "scenario" || initPayload.full === true || initPayload.autoRangeSwitch === true;
        var init = effectiveResParams(initRes);
        var homing = homingMotionSettings();
        var initTurns = 1;
        var initSpeedDegSec = homing.speedDegSec;
        var initAccelDegSec2 = homing.accelDegSec2;
        var initMotion = {
            sp: degPerSecToTicksByRes(initSpeedDegSec, initRes),
            ac: degPerSecToTicksByRes(initAccelDegSec2, initRes),
            dc: degPerSecToTicksByRes(initAccelDegSec2, initRes),
        };
        var initBasePosition = 0;
        var currentPosition = Number(driveState.position);
        if (!isFinite(currentPosition)) currentPosition = Number(pollState.position);
        if (isFinite(currentPosition) && !fullInit) initBasePosition = Math.round(currentPosition);
        var initPrTicks = Math.round(init.ca18 * initTurns);
        var initOldLimits = currentLimits;
        flow.set("resolution", initRes);
        if (fullInit) {
            global.set("velocity_sample_buffer", []);
            var pollBuf = flow.get("poll_buffer") || {};
            delete pollBuf.resolution;
            flow.set("poll_buffer", pollBuf);
        }
        var initNewLimits = syncDriveLimits(initRes);
        if (initRes !== currentRes) {
            // Auto range switch bypasses "set_resolution", so rescale the stored SP/AC/DC into
            // the new resolution ticks here too — otherwise the next set_jv/set_jp keeps the
            // old-resolution ticks and real accel/decel is off by the 40x head ratio.
            var initPreservedMotion = preserveMotionParamsForResolution(storedParams, initOldLimits, initNewLimits, currentRes);
            flow.set("motion_params", initPreservedMotion);
        }
        elmoMeta.resolution = initRes;
        elmoMeta.initMode = initMode;
        elmoMeta.initTurns = initTurns;
        elmoMeta.homing = true;
        if (verifyMotionStart) {
            elmoMeta.verifyMotionStart = true;
            var advanced = (global.get("settings") || {}).advanced || {};
            var bit = Number(advanced.homingSrBit);
            elmoMeta.homingSrBit = isFinite(bit) && bit >= 0 && bit <= 31 ? Math.round(bit) : 7;
        }
        elmoMeta.basePosition = initBasePosition;
        elmoMeta.revolutionTicks = initPrTicks;
        elmoMeta.homingSpeedDegSec = initSpeedDegSec;
        elmoMeta.homingAccelDegSec2 = initAccelDegSec2;
        elmoMeta.velocityToleranceTicks = initVelocityToleranceTicks(initRes);
        elmoMeta.motionDoneTimeoutMs = initMotionTimeoutMs(initTurns, initSpeedDegSec, initAccelDegSec2);
        elmoMeta.minMotionMs = initMinMotionMs(initSpeedDegSec, initAccelDegSec2);
        // Оба режима блокируют транспорт до завершения оборота: критерий — MS (Б1.3).
        elmoMeta.waitForMotionDone = true;
        elmoMeta.motionDoneBy = "MS";
        var homingCmds = [
            "HM[3]=3",
            "HM[4]=2",
            "HM[5]=0",
            "HM[1]=0",
            "HM[1]=1",
            "SR",
        ];
        var revolutionCmds = [
            cmdStr("SP", initMotion.sp),
            cmdStr("AC", initMotion.ac),
            cmdStr("DC", initMotion.dc),
            cmdStr("PR", initPrTicks),
        ].concat(verifyMotionStart ? ["PX", "VX", "BG"] : ["BG"]);
        if (fullInit) {
            var INIT_STAGE_DELAY = 2000;
            var CR = String.fromCharCode(13);
            var SEP = ";" + CR;
            // Стадия 3: параметры пары головок + PX=0 (только при MO=0 — Рекомендации, разд. 4).
            var stage3Cmd = resolutionSetupCmds(init).concat(["PX=0"]).join(SEP);
            var stage4Cmd = ["OL[1]", "CA[18]", "VH[2]", "SD", "QS", "PX"].join(SEP);
            var stage5AfterSo = [
                "OL[1]", "CA[18]", "VH[2]",
                cmdStr("ER[3]", init.er3),
                cmdStr("ER[2]", init.er2),
            ].concat(homingCmds, revolutionCmds);
            var stage5Cmd = [
                cmdStr("SP", initMotion.sp),
                cmdStr("AC", initMotion.ac),
                cmdStr("DC", initMotion.dc),
                "AF=0", "EC=0", "MO=1",
            ].concat(stage5AfterSo).join(SEP);
            var stage5Meta = Object.assign({}, elmoMeta, { topic: "driveInit" });
            var initSequence = context.get("initSequence");
            function scheduleStage(stage, command) {
                setTimeout(function() {
                    if (verifyMotionStart && context.get("initSequence") !== initSequence) return;
                    node.send([command]);
                }, INIT_STAGE_DELAY * stage);
            }
            node.log("driveInit " + initMode + " staged -> " + initRes + " PR=" + initPrTicks + " SP=" + initMotion.sp + " AC=" + initMotion.ac);
            node.send([{ payload: "ST" + CR, elmo_kind: "cmd", elmo_meta: { topic: "driveInit" } }]);
            scheduleStage(1, { payload: ["VX", "MO=0"].join(SEP) + CR, elmo_kind: "cmd" });
            scheduleStage(2, { payload: stage3Cmd + CR, elmo_kind: "cmd" });
            scheduleStage(3, { payload: stage4Cmd + CR, elmo_kind: "cmd" });
            scheduleStage(4, { payload: stage5Cmd + CR, elmo_kind: "cmd", elmo_meta: stage5Meta });
            return null;
        } else {
            elmoCmd = homingCmds.concat(revolutionCmds).join(";" + String.fromCharCode(13));
            node.log("driveInit " + initMode + " -> " + initRes + " PR=" + initPrTicks + " base=" + initBasePosition + " SP=" + initMotion.sp);
        }
        break;

    // ────────────────────────────────────────────────────────────────────

    // ────────────────────────────────────────────────────────────────────
    // "set_resolution" — переключение пар считывающих головок ДУ
    // payload: { resolution: "high" | "low" }
    //
    // Мануал раздел 4, алгоритм переключения головок:
    //   1. Выключить привод (SO=0) — проверяется на стороне UI
    //   2. Задать OL[1], CA[18], S1[5], KP[2], SD, QS,
    //      VH[1], VL[1], VH[2], ER[3], ER[2], TR[1], TR[3]
    //   3. Сохранить разрешение в flow context
    //   4. Пересчитать сохранённые SP/AC/DC в новое разрешение без изменения
    //      физических значений в градусах, с ограничением по допустимым пределам
    //
    // Команды разбиты на несколько строк \r для надёжного приёма по TCP.
    // ────────────────────────────────────────────────────────────────────
    case "set_resolution":
        if (!payload || !payload.resolution) {
            node.warn("set_resolution: нет payload.resolution");
            return null;
        }

        var newRes = (payload.resolution === "high") ? "high" : "low";
        elmoMeta.resolution = newRes;
        var r = effectiveResParams(newRes);
        var oldLimits = currentLimits;
        var oldMotionParams = {
            sp: Number(storedParams.sp) || 0,
            ac: Number(storedParams.ac) || 0,
            dc: Number(storedParams.dc) || 0,
        };

        flow.set("resolution", newRes);
        var newLimits = syncDriveLimits(newRes);
        var preservedMotion = preserveMotionParamsForResolution(oldMotionParams, oldLimits, newLimits, currentRes);
        flow.set("motion_params", preservedMotion);

        // Сброс счётчика PX=0 после записи параметров пары головок (Рекомендации, разд. 4;
        // Замечания п. 7 / Б1.5). Команда принимается только при выключенном двигателе —
        // MO=0 идёт первым. Буфер выборок скорости очищается: старые PX больше не сопоставимы.
        global.set("velocity_sample_buffer", []);
        var resPollBuf = flow.get("poll_buffer") || {};
        delete resPollBuf.position;
        delete resPollBuf.vh2;
        delete resPollBuf.vh2_resolution;
        flow.set("poll_buffer", resPollBuf);
        elmoCmd = ["MO=0"].concat(resolutionSetupCmds(r), [
            "PX=0",
            cmdStr("SP", preservedMotion.sp),
            cmdStr("AC", preservedMotion.ac),
            cmdStr("DC", preservedMotion.dc),
            "SP",
            "AC",
            "DC",
            "PX",
            "VH[2]",
            "TR[1]",
            "TR[2]",
            "TR[3]",
            "TR[4]",
        ]).join(";\r");

        node.log("set_resolution → " + newRes + " (OL[1]=" + r.ol1 + ", CA[18]=" + r.ca18 + ", SP=" + preservedMotion.sp + ", AC=" + preservedMotion.ac + ", DC=" + preservedMotion.dc + ")");
        break;

    // ────────────────────────────────────────────────────────────────────
    // "set_velocity" / "set_jv" — непрерывное вращение в режиме JV
    // Мануал раздел 5: AC=<ac>;DC=<dc>;JV=<ticks>;BG
    // payload: { ticks_per_sec } или { ticks, ac_ticks?, dc_ticks? }
    // ────────────────────────────────────────────────────────────────────
    case "set_velocity":
    case "set_jv":
        if (!payload) { node.warn("set_jv: нет payload"); return null; }

        var jvValue = payload.ticks_per_sec !== undefined ? payload.ticks_per_sec : payload.ticks;
        var jv = validateSignedSpeed("set_jv/JV", jvValue, currentLimits, true);
        var jvAc = validateAccel(
            "set_jv/AC",
            payload.ac_ticks !== undefined ? payload.ac_ticks : storedParams.ac,
            currentLimits.accel_min_ticks,
            currentLimits.accel_max_ticks
        );
        var jvDc = validateAccel(
            "set_jv/DC",
            payload.dc_ticks !== undefined ? payload.dc_ticks : storedParams.dc,
            currentLimits.decel_min_ticks,
            currentLimits.decel_max_ticks
        );
        if (!jv.ok || !jvAc.ok || !jvDc.ok) return null;

        elmoMeta.setpointDegS = currentLimits.ticks_per_deg ? (jv.value / currentLimits.ticks_per_deg) : 0;
        flow.set("motion_params", { sp: storedParams.sp, ac: jvAc.value, dc: jvDc.value });
        // Окно скорости MS: TR[3] текущей пары из настроек пишется перед каждым JV — привод
        // всегда работает с окном из настроек, что бы ни было записано в него раньше.
        var jvTr3 = Math.max(1, Math.round(effectiveResParams(currentRes).tr3));
        if (verifyMotionStart) {
            elmoMeta.verifyMotionStart = true;
            elmoMeta.targetVelocity = jv.value;
            elmoMeta.speedRequestId = payload.speedRequestId;
            elmoMeta.speedWindowTicks = jvTr3;
        }
        elmoCmd = joinCmds(
            cmdStr("TR[3]", jvTr3),
            cmdStr("AC", jvAc.value),
            cmdStr("DC", jvDc.value),
            cmdStr("JV", jv.value),
            verifyMotionStart && "PX",
            verifyMotionStart && "VX",
            "BG",
            "JV",
            "JP",
            "MS",
            "VX"
        );
        break;

    // ────────────────────────────────────────────────────────────────────
    // "set_jp" — непрерывное вращение в режиме JP
    // Мануал раздел 5: AC=<ac>;DC=<dc>;JP=<ticks>;BG
    // payload: { ticks, ac_ticks?, dc_ticks? }
    // JP=0;BG — остановка с заданным замедлением DC
    // ────────────────────────────────────────────────────────────────────
    case "set_jp":
        if (!payload) { node.warn("set_jp: нет payload"); return null; }

        var jp = validateSignedSpeed("set_jp/JP", payload.ticks, currentLimits, true);
        var jpAc = validateAccel(
            "set_jp/AC",
            payload.ac_ticks !== undefined ? payload.ac_ticks : storedParams.ac,
            currentLimits.accel_min_ticks,
            currentLimits.accel_max_ticks
        );
        var jpDc = validateAccel(
            "set_jp/DC",
            payload.dc_ticks !== undefined ? payload.dc_ticks : storedParams.dc,
            currentLimits.decel_min_ticks,
            currentLimits.decel_max_ticks
        );
        if (!jp.ok || !jpAc.ok || !jpDc.ok) return null;
        if (verifyMotionStart) {
            elmoMeta.verifyMotionStart = true;
            elmoMeta.targetVelocity = jp.value;
            elmoMeta.speedRequestId = payload.speedRequestId;
            elmoMeta.speedWindowTicks = Math.max(1, Math.round(effectiveResParams(currentRes).tr3));
        }

        flow.set("motion_params", { sp: storedParams.sp, ac: jpAc.value, dc: jpDc.value });
        elmoCmd = joinCmds(
            cmdStr("AC", jpAc.value),
            cmdStr("DC", jpDc.value),
            cmdStr("JP", jp.value),
            verifyMotionStart && "PX",
            verifyMotionStart && "VX",
            "BG",
            "JV",
            "JP",
            "MS",
            "VX"
        );
        break;

    // ────────────────────────────────────────────────────────────────────
    // "set_absolute_position" — абсолютное позиционирование PA
    // payload: { ticks, sp_ticks?, ac_ticks?, dc_ticks? }
    // Мануал раздел 5: SP; AC; DC; PA=N; BG
    // ────────────────────────────────────────────────────────────────────
    case "set_absolute_position":
        if (!payload) { node.warn("set_absolute_position: нет payload"); return null; }

        var pa = Math.round(Number(payload.ticks) || 0);
        if (Math.abs(pa) > 2147483647) { node.warn("set_absolute_position: PA=" + pa + " вне диапазона int32 привода"); return null; }
        var pa_sp = Math.round(payload.sp_ticks !== undefined ? payload.sp_ticks : storedParams.sp);
        var pa_ac = Math.round(payload.ac_ticks !== undefined ? payload.ac_ticks : storedParams.ac);
        var pa_dc = Math.round(payload.dc_ticks !== undefined ? payload.dc_ticks : storedParams.dc);

        var paSpCheck = validateUnsignedSpeed("set_absolute_position/SP", pa_sp, currentLimits, true);
        var paAcCheck = validateAccel("set_absolute_position/AC", pa_ac, currentLimits.accel_min_ticks, currentLimits.accel_max_ticks);
        var paDcCheck = validateAccel("set_absolute_position/DC", pa_dc, currentLimits.decel_min_ticks, currentLimits.decel_max_ticks);
        if (!paSpCheck.ok || !paAcCheck.ok || !paDcCheck.ok) return null;

        if (paSpCheck.value === 0) {
            node.warn("set_absolute_position: SP=0, движение невозможно. Задайте скорость в «Параметры движения».");
            return null;
        }

        elmoCmd = [
            cmdStr("SP", paSpCheck.value),
            cmdStr("AC", paAcCheck.value),
            cmdStr("DC", paDcCheck.value),
            cmdStr("PA", pa),
            "BG",
        ].join(";\r");
        break;

    // ────────────────────────────────────────────────────────────────────
    // "set_relative_position" — относительное позиционирование PR
    // payload: { ticks, sp_ticks?, ac_ticks?, dc_ticks? }
    // Мануал раздел 5: SP; AC; DC; PR=N; BG
    // ticks знаковый: + по часовой, − против часовой
    // ────────────────────────────────────────────────────────────────────
    case "set_relative_position":
        if (!payload) { node.warn("set_relative_position: нет payload"); return null; }

        var pr = Math.round(Number(payload.ticks) || 0);
        if (Math.abs(pr) > 2147483647) { node.warn("set_relative_position: PR=" + pr + " вне диапазона int32 привода"); return null; }
        var pr_sp = Math.round(payload.sp_ticks !== undefined ? payload.sp_ticks : storedParams.sp);
        var pr_ac = Math.round(payload.ac_ticks !== undefined ? payload.ac_ticks : storedParams.ac);
        var pr_dc = Math.round(payload.dc_ticks !== undefined ? payload.dc_ticks : storedParams.dc);

        var prSpCheck = validateUnsignedSpeed("set_relative_position/SP", pr_sp, currentLimits, true);
        var prAcCheck = validateAccel("set_relative_position/AC", pr_ac, currentLimits.accel_min_ticks, currentLimits.accel_max_ticks);
        var prDcCheck = validateAccel("set_relative_position/DC", pr_dc, currentLimits.decel_min_ticks, currentLimits.decel_max_ticks);
        if (!prSpCheck.ok || !prAcCheck.ok || !prDcCheck.ok) return null;

        if (prSpCheck.value === 0) {
            node.warn("set_relative_position: SP=0, движение невозможно. Задайте скорость в «Параметры движения».");
            return null;
        }

        elmoCmd = joinCmds(
            cmdStr("SP", prSpCheck.value),
            cmdStr("AC", prAcCheck.value),
            cmdStr("DC", prDcCheck.value),
            cmdStr("PR", pr),
            "BG"
        );
        break;

    default:
        node.warn("Неизвестный топик: " + topic);
        return null;
}

// Append CR required by Elmo Platinum.
if (!elmoCmd) {
    node.warn("CommandHandler: empty ELMO command for topic " + topic);
    return null;
}
msg.payload = elmoCmd + "\r";
msg.elmo_topic = topic;
msg.elmo_kind = "cmd";
if (Object.keys(elmoMeta).length) msg.elmo_meta = elmoMeta;

node.log("[" + topic + "] → " + elmoCmd);

return msg;

// ─────────────────────────────────────────────────────────────────────────
// UNIVERSAL Elmo Parser + SR decode
//
// Ключевые принципы:
//   • msg.topic НИКОГДА не меняется — фронт фильтрует сам
//   • Единый токенизатор для всех форматов ответов Elmo:
//       Формат A: PARAM=VALUE[;PARAM=VALUE;…]  → "SP=9102;AC=910;DC=910"
//       Формат B: PARAM;VALUE[;PARAM;VALUE;…]  → "MS;0;PX;2808089"
//       (\r\n внутри строки нормализуется в ";")
//   • Нет init-буфера: SP/AC/DC идут напрямую в payload
//   • buildPollData возвращает полный снимок poll-буфера с оригинальным topic
// ─────────────────────────────────────────────────────────────────────────

// Давление (Б4.1): линейный пересчёт напряжения аналогового входа ELMO в единицы давления.
// Коэффициенты — технологические настройки (уточняются Заказчиком), по умолчанию 1·U + 0.
function pressureSettings() {
    var settings = global.get("settings") || {};
    var p = (settings.advanced && settings.advanced.pressure) || {};
    var scale = Number(p.scalePerVolt);
    var offset = Number(p.offset);
    var warn = Number(p.warnBelow);
    return {
        enabled: p.enabled !== false,
        scale: isFinite(scale) ? scale : 1,
        offset: isFinite(offset) ? offset : 0,
        unit: p.unit || "\u0430\u0442\u043c",
        warnBelow: isFinite(warn) ? warn : null
    };
}

function homingSrBit() {
    var settings = global.get("settings") || {};
    var bit = Number(settings.advanced && settings.advanced.homingSrBit);
    return isFinite(bit) && bit >= 0 && bit <= 31 ? Math.round(bit) : 7;
}

function decodeSR(sr) {
    var bin = (sr >>> 0).toString(2).padStart(32, "0");
    var lowBits = bin.slice(-4);
    var amplifierCode = sr & 0xF;
    var errors = [];
    var errorsEn = [];
    // Тексты кодов усилителя на русском и английском (интерфейс выбирает по языку).
    var amplifierCodeMap = {
        0: ["Ошибок нет", "No errors"],
        3: ["Пониженное напряжение", "Under-voltage"],
        5: ["Повышенное напряжение", "Over-voltage"],
        7: ["Цепь безопасности STO (нет давления воздуха)", "Safety / STO (no air pressure)"],
        9: ["Ошибка датчика", "Feedback sensor error"],
        11: ["Короткое замыкание", "Short circuit"],
        12: ["Аварийная остановка (Abort)", "Abort"],
        13: ["Перегрев привода", "Drive over-temperature"],
        14: ["Перегрев двигателя", "Motor over-temperature"],
        15: ["Дополнительная аварийная остановка (Abort)", "Additional abort"],
    };
    var amplifierPair = amplifierCodeMap.hasOwnProperty(amplifierCode)
        ? amplifierCodeMap[amplifierCode]
        : ["Неизвестный код ошибки SR: " + amplifierCode, "Unknown SR error code: " + amplifierCode];
    var amplifierText = amplifierPair[0];
    var amplifierTextEn = amplifierPair[1];

    if (amplifierCode !== 0) {
        errors.push("SR[0-3]=" + amplifierCode + ": " + amplifierText);
        errorsEn.push("SR[0-3]=" + amplifierCode + ": " + amplifierTextEn);
    }

    return {
        raw: sr,
        binary: bin,
        // Код 7 усилителя = Safety/STO. На стенде STO заведён на реле давления воздуха,
        // поэтому этот признак показывается оператору как срабатывание защиты по давлению (Б4.1).
        sto_active: amplifierCode === 7,
        // Бит SR (по умолчанию 7, settings.advanced.homingSrBit) дублирует HM[1]: 1 — поиск
        // нулевой метки активен, 0 — метка захвачена или поиск не запущен (Рекомендации, разд. 6).
        homing_active: ((sr >>> homingSrBit()) & 1) === 1,
        amplifier_bits_0_3: lowBits,
        amplifier_code: amplifierCode,
        amplifier_text: amplifierText,
        amplifier_text_en: amplifierTextEn,
        ok: amplifierCode === 0,
        errors: errors,
        errors_en: errorsEn,
        summary: amplifierCode === 0 ? "Ошибок нет" : ("Код " + amplifierCode + ": " + amplifierText),
        summary_en: amplifierCode === 0 ? "No errors" : ("Code " + amplifierCode + ": " + amplifierTextEn),
    };
}

function parseElmoNumber(value) {
    var text = String(value || "").trim();
    if (!text) return NaN;
    return Number(text);
}

// Предел скорости = VH[2] пары головок (Замечания п. 6): номинал из таблицы, поверх — значение,
// прочитанное из привода для этой пары (global.drive_vh2_ticks). Нижнего предела нет.
function nominalVh2Ticks(resolution) {
    return (resolution === "high") ? 34952533 : 6553600;
}

function driveVh2TicksFor(resolution, poll) {
    if (poll && poll.vh2 !== undefined && poll.vh2_resolution === resolution) {
        var live = Math.round(Number(poll.vh2));
        if (isFinite(live) && live > 0) return live;
    }
    var map = global.get("drive_vh2_ticks") || {};
    var saved = Math.round(Number(map[resolution]));
    if (isFinite(saved) && saved > 0) return saved;
    return nominalVh2Ticks(resolution);
}

function buildDriveLimitsFromPoll(poll) {
    var resolution = flow.get("resolution") || poll.resolution || "high";
    var ticksPerDeg = (resolution === "high") ? (262144000 / 360) : (6553600 / 360);
    var defaultAccel = (resolution === "high") ? 131072000 : 3276800;
    var speedMaxTicks = driveVh2TicksFor(resolution, poll);
    var accelMaxTicks = Math.min(
        poll.sd !== undefined ? Math.round(Number(poll.sd)) : defaultAccel,
        poll.vh1 !== undefined ? Math.round(Number(poll.vh1)) : defaultAccel,
        poll.vl1 !== undefined ? Math.round(Number(poll.vl1)) : defaultAccel
    );
    return {
        resolution: resolution,
        ticks_per_deg: ticksPerDeg,
        speed_min_deg: 0,
        speed_max_deg: speedMaxTicks / ticksPerDeg,
        speed_min_ticks: 0,
        speed_max_ticks: speedMaxTicks,
        drive_vh2_ticks: speedMaxTicks,
        speed_min_validate_ticks: 0,
        speed_max_validate_ticks: speedMaxTicks,
        accel_min_ticks: 0,
        accel_max_ticks: accelMaxTicks,
        accel_max_deg: accelMaxTicks / ticksPerDeg,
        decel_min_ticks: 0,
        decel_max_ticks: accelMaxTicks,
        decel_max_deg: accelMaxTicks / ticksPerDeg,
    };
}

// Окно оценки скорости по TM/PX (settings.advanced.velocityWindowMs, по умолчанию 1 с). Было 3 с:
// средняя скорость за 3 с отставала от привода на ~1,5 с (плюс период опроса) — при разгоне и
// остановке отображаемая скорость заметно запаздывала.
function velocityWindowUs() {
    var adv = (global.get("settings") || {}).advanced || {};
    var ms = Number(adv.velocityWindowMs);
    if (!isFinite(ms)) ms = 1000;
    return Math.min(3000, Math.max(200, ms)) * 1000;
}
function estimateVelocityFromSamples(samples) {
    var maxSpanUs = velocityWindowUs();
    if (!Array.isArray(samples) || samples.length < 2) return null;
    var last = samples[samples.length - 1];
    var first = null;
    for (var i = samples.length - 2; i >= 0; i--) {
        var candidate = samples[i];
        var dtUs = Number(last.tmUs) - Number(candidate.tmUs);
        if (!(dtUs > 0)) continue;
        if (dtUs > maxSpanUs) break;
        first = candidate;
    }
    if (!first) return null;
    var spanUs = Number(last.tmUs) - Number(first.tmUs);
    if (spanUs < 200000) return null;
    var ticksPerSec = (Number(last.positionTicks) - Number(first.positionTicks)) * 1000000 / spanUs;
    if (!isFinite(ticksPerSec)) return null;
    return {
        ticksPerSec: ticksPerSec,
        dtSec: spanUs / 1000000,
        positionDeltaTicks: Number(last.positionTicks) - Number(first.positionTicks),
    };
}

function appendVelocitySample(resolution, positionTicks, tmUs) {
    var sample = { resolution: resolution, positionTicks: positionTicks, tmUs: tmUs };
    var samples = global.get("velocity_sample_buffer") || [];
    samples = samples.filter(function (s) {
        if (!s || s.resolution !== resolution) return false;
        var oldTm = Number(s.tmUs);
        var oldPx = Number(s.positionTicks);
        if (!isFinite(oldTm) || !isFinite(oldPx)) return false;
        var ageUs = tmUs - oldTm;
        return ageUs >= 0 && ageUs <= 5000000;
    });
    samples.push(sample);
    global.set("velocity_sample_buffer", samples);
    return samples;
}

function updateVelocityEstimate(poll, hasFreshSample) {
    var resolution = flow.get("resolution") || poll.resolution || "high";
    var rawVelocity = Number(poll.velocity);
    poll.velocity_raw = isFinite(rawVelocity) ? rawVelocity : 0;

    var estimate = null;
    if (hasFreshSample) {
        var positionTicks = Number(poll.position);
        var tmUs = Number(poll.tm_us);
        if (isFinite(positionTicks) && isFinite(tmUs)) {
            var samples = appendVelocitySample(resolution, positionTicks, tmUs);
            poll.velocity_sample_count = samples.length;
            estimate = estimateVelocityFromSamples(samples);
            if (estimate) {
                poll.velocity_derived = Math.round(estimate.ticksPerSec * 1000) / 1000;
                poll.velocity_derived_dt_sec = estimate.dtSec;
                poll.velocity_derived_delta_ticks = estimate.positionDeltaTicks;
                poll.velocity_derived_tm_us = tmUs;
            } else {
                poll.velocity_derived = null;
