// Регистр состояния БУН (topic bun_state) во время движения. Решение «закончил движение» принимается
// на следующем отсчёте угла (end_pending): угол и состояние приходят разными сообщениями.
function onBunState(state, st) {
    var cfg = readConfig();
    var code = Number(st.code);
    state.last_state_code = code;
    if (!state.go_at || state.end_pending) { saveState(state); return null; }
    var pass = state.phase === 'zero_pass';
    if (state.phase === 'zero_pass_stop') {
        if (isMovingState(code)) { saveState(state); return null; }
        // БУН остановился после stop — уставка и GO.
        return continueAfterPass(state);
    }
    if (isMovingState(code)) {
        state.state_moving_seen = true;
        state.idle_samples = 0;
        saveState(state);
        return null;
    }
    if (state.state_moving_seen) {
        // БУН вышел из движения сам.
        if (pass) {
            if (state.status === 'moving') finishFault(state, cfg, 'stalled');
            else finishManualPassFault(state, cfg, 'stalled');
