    if (state.idle_samples < cfg.stateStartSamples) { saveState(state); return null; }
    if (state.status === 'moving') { finishFault(state, cfg, 'no_motion'); return null; }
    if (pass) { finishManualPassFault(state, cfg, 'no_motion'); return null; }
