        status: auto ? 'moving' : 'manual_go', phase: 'zero_pass', jog_cmd: jog,
        target_seconds: bunTarget, operator_target_seconds: opTarget, correction_arcsec: corr.applied ? corr.arcsec : null,
        start_angle_seconds: startAngle, last_angle_seconds: startAngle, pass_start_remaining: Math.abs(bunTarget - startAngle),
        error_seconds: Math.abs(bunTarget - startAngle), stable_count: 0,
