    saveState(state);
    node.status({ fill: 'blue', shape: 'ring', text: 'zero pass → ' + bunTarget + ' sec' });
    var ru = (auto ? 'Автонаклон: старт, уставка ' : 'Ручной наклон: уставка ') + fmtDeg(opTarget) + '°' + correctionNote(corr) +
        ' (текущий угол ' + fmtDeg(startAngle) + '°); короткий путь пересекает упор ±180° — БУН сначала идёт через 0 командой ' + lbl[0] +
