    var en = (auto ? 'Auto tilt: start, setpoint ' : 'Manual tilt: setpoint ') + fmtDeg(opTarget) + '°' + correctionNoteEn(corr) +
        ' (current angle ' + fmtDeg(startAngle) + '°); the short path crosses the ±180° stop — BUN first moves through 0 with ' + lbl[1] +
