    } else if (reason === 'stalled') {
        ru = 'Ручной наклон: БУН прекратил движение ' + lbl[0] + ' на ' + angle + '° до выхода из зоны упора ±180° — состояние ' + stateText(state.last_state_code) + ' (уставка ' + target + '°); БУН остановлен';
        en = 'Manual tilt: BUN stopped the ' + lbl[1] + ' movement at ' + angle + '° before leaving the ±180° stop zone — state ' + stateTextEn(state.last_state_code) + ' (setpoint ' + target + '°); BUN stopped';
