        en = 'Manual tilt: while passing through 0 the angle moves away from the setpoint (angle ' + angle + '°, setpoint ' + target + '°) — command ' + lbl[1] + ' moves the wrong way (setting tiltJogUpIncreases); BUN stopped';
    } else if (reason === 'no_data') {
