    state.phase = 'zero_pass_stop';
    state.message = who + ': БУН на ' + fmtDeg(state.last_angle_seconds) + '°, путь к ' + fmtDeg(state.target_seconds) + '° идёт через 0 — остановка и GO';
    state.message_en = whoEn + ': BUN at ' + fmtDeg(state.last_angle_seconds) + '°, the path to ' + fmtDeg(state.target_seconds) + '° goes through 0 — stop and GO';
