    state.last_sample_at = now;
    state.updated_at = now;
    state.error_seconds = Math.abs(angle - Number(state.target_seconds));
    if (state.phase !== 'zero_pass' || !state.go_at) { saveState(state); return null; }
    var remaining = Math.abs(Number(state.target_seconds) - angle);
    if (remaining > Number(state.pass_start_remaining) + cfg.wrongDirectionSec) {
        if (state.status === 'moving') finishFault(state, cfg, 'wrong_direction');
        else finishManualPassFault(state, cfg, 'wrong_direction');
        return null;
    }
    if (remaining <= cfg.rangeSec - cfg.zeroPassMarginSec) return endZeroPass(state, cfg);
    saveState(state);
    return [null, null, null, null, uiMsg(state)];
