    var c = tiltCorrection();
    if (!c.apply) return { applied: false, arcsec: 0, note: '', noteEn: '' };
    if (c.dphi === null) {
        return { applied: false, arcsec: 0, warn: true,
            note: '; поправка к углу наклона не применена: не определена', noteEn: '; tilt correction not applied: not determined' };
    }
    if (c.phiSec !== null && Math.abs(target - c.phiSec) > cfg.corrAngleTolSec) {
        return { applied: false, arcsec: 0, warn: true,
            note: '; поправка к углу наклона не применена: определена при ' + fmtDeg(c.phiSec) + '°',
            noteEn: '; tilt correction not applied: determined at ' + fmtDeg(c.phiSec) + '°' };
    }
    var arcsec = Math.round(c.dphi);
    var signed = (arcsec >= 0 ? '+' : '') + arcsec;
    return { applied: true, arcsec: arcsec,
        note: ', поправка Δφ ' + signed + '″ → уставка БУН ' + fmtDeg(target + arcsec) + '°',
        noteEn: ', correction Δφ ' + signed + '″ → BUN setpoint ' + fmtDeg(target + arcsec) + '°' };
