// Ручной режим: уставка + GO, тормозом управляет оператор; итог — когда БУН остановится.
function beginManualGo(opTarget, bunTarget, corr, afterPass) {
    var manualCfg = readConfig();
    clearTimers();
    var manualState = startManualTrack('manual_go', bunTarget,
        'Ручной режим: уставка ' + fmtDeg(bunTarget) + '° отправлена на БУН, тормозом управляет оператор',
        'Manual mode: setpoint ' + fmtDeg(bunTarget) + '° sent to BUN, the operator controls the brake');
    manualState.operator_target_seconds = opTarget;
    manualState.correction_arcsec = corr.applied ? corr.arcsec : null;
    saveState(manualState);
    node.status({ fill: 'grey', shape: 'dot', text: 'manual target ' + bunTarget + ' sec' });
    var ru = afterPass
        ? 'Ручной наклон: проход через 0 выполнен (угол ' + fmtDeg(manualState.start_angle_seconds) + '°), уставка ' + fmtDeg(bunTarget) + '° и GO'
        : 'Ручной наклон: уставка ' + fmtDeg(opTarget) + '°' + correctionNote(corr) + ' (текущий угол ' + fmtDeg(manualState.start_angle_seconds) + '°), тормозом управляет оператор';
    var en = afterPass
        ? 'Manual tilt: the pass through 0 is done (angle ' + fmtDeg(manualState.start_angle_seconds) + '°), setpoint ' + fmtDeg(bunTarget) + '° and GO'
        : 'Manual tilt: setpoint ' + fmtDeg(opTarget) + '°' + correctionNoteEn(corr) + ' (current angle ' + fmtDeg(manualState.start_angle_seconds) + '°), the operator controls the brake';
    node.send([{ topic: 'bun_cmd_setpoint', payload: bunTarget }, null, null, journal(ru, en, corr.warn ? 'warning' : 'info'), uiMsg(manualState)]);
    var manualGoTimer = setTimeout(function () {
        node.send([null, { topic: 'bun_cmd', payload: 'go' }, null, null, null]);
    }, manualCfg.goDelayMs);
    context.set('bun_auto_go_timer', manualGoTimer);
