    pushLog('Записано: omega=' + omega.toFixed(4) + ' град/с, delta=' + errPct.toFixed(2) + '%', 'record', 'Recorded: omega=' + omega.toFixed(4) + ' deg/s, delta=' + errPct.toFixed(2) + '%');
    return { protocolMsg: { payload: protoRow, filename: protocolFile }, dataMsg: null };
}

function clearRecordingTimer() {
    var existing = context.get('rec_timer');
    if (existing) { clearTimeout(existing); }
    context.set('rec_timer', null);
}
function armRecordingTimer(protocolFile, durSec) {
    clearRecordingTimer();
    var ms = Math.max(1, Math.round(safeNumber(durSec, 60))) * 1000;
    var timer = setTimeout(function () {
        context.set('rec_timer', null);
        if (!global.get('is_recording')) return;
        var pf = global.get('protocol_filename');
        if (!pf || !global.get('protocol_open')) return;
        var result = finalizeRecording(pf, getRawPreference());
        global.set('recording_ends_at', 0);
        var state = saveJournalState(getJournalState());
        node.send([
            result.protocolMsg,
            result.dataMsg,
            [getLogsMessage(), getJournalMessage(state)],
            null,
            null
        ]);
        if (typeof node.done === 'function') node.done();
    }, ms);
    context.set('rec_timer', timer);
}

if (topic === 'reread') {
    var rereadState = saveJournalState(getJournalState());
    return [null, null, [getLogsMessage(), getJournalMessage(rereadState)], null, null];
}

if (topic === 'journal_event') {
    var journalPayload = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
    pushLog(journalPayload.message || String(msg.payload || 'Событие сценария'), journalPayload.type || 'info', journalPayload.message_en || (journalPayload.message ? '' : 'Scenario event'), journalPayload.source || '');
    var journalEventState = saveJournalState(getJournalState());
    return [null, null, [getLogsMessage(), getJournalMessage(journalEventState)], null, null];
}

if (topic === 'cancel_recording') {
    clearRecordingTimer();
    global.set('recording_ends_at', 0);
    setRecordingFlags(false, false);
    global.set('angle_buffer', []);
    var cancelPayload = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
    pushLog(cancelPayload.message || 'Запись отменена без сохранения измерения', 'warning', cancelPayload.message_en || (cancelPayload.message ? '' : 'Recording cancelled, the measurement is not saved'));
    var cancelState = saveJournalState(getJournalState());
    return [null, null, [getLogsMessage(), getJournalMessage(cancelState)], null, null];
}

if (topic === 'open_protocol') {
    if (global.get('protocol_open')) {
        return [null, null, [getLogsMessage(), getJournalMessage(saveJournalState(getJournalState()))], null, null];
    }
    var stamp = tsFile(now);
    var fname = 'C:\\NC3\\protocols\\protocol_' + stamp + '.txt';
    global.set('protocol_filename', fname);
    global.set('protocol_open', true);
    setRecordingFlags(false, false);

    // bun_angle — угловые секунды; в заголовок — угол БУН в градусах и поправка к углу наклона
    // (методика «Калибровка БЕП»): Δφ, K и была ли Δφ прибавлена к последней уставке.
    var tiltArcsec = safeNumber(global.get('bun_angle'), 0);
    var tilt = tiltArcsec / 3600;
    var tiltCorr = global.get('tilt_correction') || {};
    var corrApplied = tiltCorr.appliedToSetpointArcsec !== null && tiltCorr.appliedToSetpointArcsec !== undefined;
    var range = global.get('current_range') || 'high';
    var res = (range === 'high') ? '0.005' : '0.2';
    var settings = global.get('settings') || {};
    var angleSavingMode = (settings.general && settings.general.angleSavingMode) || 'header';

    var headerLines = [
        '=====',
        '# Protocol file ID ' + stamp,
        '# Created: ' + nowStr(now),
        'Playback_range               ' + range,
        'Encoder_resolution           ' + res + ' # degree',
        'Date                         ' + nowStr(now).slice(0, 10),
        'Time                         ' + nowStr(now).slice(11),
        '-------------------',
        'Speed_value Error Data_file # degree/s %',
    ];
    if (angleSavingMode !== 'none') {
        headerLines.splice(3, 0, 'Rotation_axis_tilt_angle     ' + tilt.toFixed(6) + ' # degree, BUN angle',
            'Tilt_angle_correction        ' + (corrApplied ? Number(tiltCorr.appliedToSetpointArcsec).toFixed(0) : '0') +
            ' # arcsec, ' + (corrApplied ? 'added to the tilt setpoint' : 'not applied') +
            (tiltCorr.arcsec !== null && tiltCorr.arcsec !== undefined ? ', measured dphi ' + Number(tiltCorr.arcsec).toFixed(1) + ' arcsec, K ' + tiltCorr.k : ''));
    }
    var header = headerLines.join('\n') + '\n';

    pushLog('Протокол открыт: ' + fname, 'info', 'Protocol opened: ' + fname);
    var state = getJournalState();
    state.selectedProtocol = fname;
    state.selectedFile = fname;
    state.selectedKind = 'protocol';
    state.selectedName = basename(fname);
    state.error = '';
    saveJournalState(state);
    return [
        { payload: header, filename: fname },
        null,
        [getLogsMessage(), getJournalMessage(state)],
        null,
        null
    ];
}

if (topic === 'close_protocol') {
    var pfClose = global.get('protocol_filename');
    if (!pfClose || !global.get('protocol_open')) {
        return null;
    }

    clearRecordingTimer();
    global.set('recording_ends_at', 0);

    var protocolMessages = [];
    var dataMessage = null;
    if (global.get('is_recording')) {
        var closeResult = finalizeRecording(pfClose, getRawPreference());
        if (closeResult.protocolMsg) protocolMessages.push(closeResult.protocolMsg);
        dataMessage = closeResult.dataMsg;
    }

    global.set('protocol_open', false);
    global.set('protocol_filename', null);
    setRecordingFlags(false, false);
    pushLog('Протокол закрыт: ' + pfClose, 'info', 'Protocol closed: ' + pfClose);
    protocolMessages.push({ payload: '=====\n', filename: pfClose });

    var closeState = saveJournalState(getJournalState());
    return [
        protocolMessages,
        dataMessage,
        [getLogsMessage(), getJournalMessage(closeState)],
        null,
        null
    ];
}

if (topic === 'start_recording') {
    if (!global.get('protocol_open') || !global.get('protocol_filename')) {
        pushLog('Ошибка: нельзя начать запись без открытого протокола', 'error', 'Error: recording cannot start without an open protocol');
        var startNoProtoState = saveJournalState(getJournalState());
        return [null, null, [getLogsMessage(), getJournalMessage(startNoProtoState)], null, null];
    }
    var saveRawStart = (msg.payload && msg.payload.save_raw_data !== undefined)
        ? !!msg.payload.save_raw_data
        : getRawPreference();
    setRecordingFlags(true, saveRawStart);
    global.set('angle_buffer', []);
    var spTicks = (msg.payload && msg.payload.sp_ticks) ? Number(msg.payload.sp_ticks) : 0;
    global.set('velocity_setpoint_ticks', spTicks);
    var durSec = getRecordingDurationSec(msg.payload && msg.payload.duration_sec);
    global.set('recording_duration_sec', durSec);
    global.set('recording_save_raw_data', saveRawStart);
    global.set('recording_ends_at', Date.now() + durSec * 1000);
    armRecordingTimer(global.get('protocol_filename'), durSec);
    pushLog('Запись запущена', 'record', 'Recording started');
    var startState = saveJournalState(getJournalState());
    return [null, null, [getLogsMessage(), getJournalMessage(startState)], null, null];
}

if (topic === 'stop_recording' || topic === 'record_measurement') {
    clearRecordingTimer();
    global.set('recording_ends_at', 0);
    var pf = global.get('protocol_filename');
    if (!pf || !global.get('protocol_open')) {
        pushLog('Ошибка: протокол не открыт', 'error', 'Error: no protocol is open');
        var noProtoState = saveJournalState(getJournalState());
        return [null, null, [getLogsMessage(), getJournalMessage(noProtoState)], null, null];
    }

    if (!global.get('is_recording')) {
        pushLog('Запись уже остановлена', 'info', 'Recording is already stopped');
        var idleRecordState = saveJournalState(getJournalState());
        return [null, null, [getLogsMessage(), getJournalMessage(idleRecordState)], null, null];
    }

    if (msg.payload && msg.payload.duration_sec !== undefined) {
        global.set('recording_duration_sec', getRecordingDurationSec(msg.payload.duration_sec));
    }

    var saveRaw = (msg.payload && msg.payload.save_raw_data) !== undefined
        ? !!msg.payload.save_raw_data
        : getRawPreference();
    global.set('recording_save_raw_data', saveRaw);
    var result = finalizeRecording(pf, saveRaw);
    var stateAfterRecord = saveJournalState(getJournalState());
    return [
        result.protocolMsg,
        result.dataMsg,
        [getLogsMessage(), getJournalMessage(stateAfterRecord)],
        null,
        null
    ];
}

if (topic === 'journal_refresh' && msg.journalAction !== 'list_result') {
    return [null, null, null, { topic: 'journal_refresh', journalAction: 'list_result' }, null];
}

if (topic === 'journal_refresh' && msg.journalAction === 'list_result') {
    var refreshedState = getJournalState();
    refreshedState.files = parseListPayload(msg.payload);
    var availablePaths = refreshedState.files.map(function(file) { return file.path; });

    if (refreshedState.selectedProtocol && availablePaths.indexOf(refreshedState.selectedProtocol) === -1) {
        refreshedState.selectedProtocol = '';
    }
    if (!refreshedState.selectedProtocol) {
        var currentProtocol = refreshedState.protocolFile;
        if (currentProtocol && availablePaths.indexOf(currentProtocol) >= 0) {
            refreshedState.selectedProtocol = currentProtocol;
        } else if (refreshedState.files.length) {
            refreshedState.selectedProtocol = refreshedState.files[0].path;
        }
    }
    if (!refreshedState.selectedFile && refreshedState.selectedProtocol) {
        refreshedState.selectedFile = refreshedState.selectedProtocol;
        refreshedState.selectedKind = 'protocol';
        refreshedState.selectedName = basename(refreshedState.selectedFile);
    }
    refreshedState.error = '';
    saveJournalState(refreshedState);

    var shouldLoadSelected = refreshedState.selectedFile && (!Array.isArray(refreshedState.rows) || !refreshedState.rows.length);
    return [
        null,
        null,
        getJournalMessage(refreshedState),
        null,
        shouldLoadSelected ? {
            topic: 'journal_open_file',
            journalAction: 'file_result',
            filename: refreshedState.selectedFile,
            kind: refreshedState.selectedKind || 'protocol',
            selectedProtocol: refreshedState.selectedProtocol || refreshedState.selectedFile
        } : null
    ];
}

if (topic === 'journal_open_file' && msg.journalAction !== 'file_result') {
    var requested = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
    var requestedFile = requested.filename || '';
    if (!requestedFile) return null;

    var openState = getJournalState();
    openState.rows = [];
    openState.selectedFile = requestedFile;
    openState.selectedKind = requested.kind === 'data' ? 'data' : 'protocol';
    openState.selectedName = basename(requestedFile);
    if (openState.selectedKind === 'protocol') {
        openState.selectedProtocol = requestedFile;
    } else if (requested.selectedProtocol) {
        openState.selectedProtocol = requested.selectedProtocol;
    }
    openState.error = '';
    saveJournalState(openState);
    return [
        null,
        null,
        getJournalMessage(openState),
        null,
        {
            topic: 'journal_open_file',
            journalAction: 'file_result',
            filename: requestedFile,
            kind: openState.selectedKind,
            selectedProtocol: openState.selectedProtocol
        }
    ];
}

if (topic === 'journal_open_file' && msg.journalAction === 'file_result') {
    var loadedState = getJournalState();
    if (msg.filename && loadedState.selectedFile && msg.filename !== loadedState.selectedFile) return null;
    loadedState.selectedFile = msg.filename || loadedState.selectedFile;
    loadedState.selectedKind = msg.kind || loadedState.selectedKind || 'protocol';
    loadedState.selectedName = basename(loadedState.selectedFile);
    if (loadedState.selectedKind === 'protocol') {
        loadedState.selectedProtocol = loadedState.selectedFile;
    } else if (msg.selectedProtocol) {
        loadedState.selectedProtocol = msg.selectedProtocol;
    }

    if (msg.error) {
        loadedState.rows = [];
        var openError = String(msg.error.message || msg.error || '');
        loadedState.error = 'Не удалось открыть файл' + (openError ? ': ' + openError : '');
        loadedState.error_en = 'Cannot open the file' + (openError ? ': ' + openError : '');
        saveJournalState(loadedState);
        return [null, null, getJournalMessage(loadedState), null, null];
    }

    var fileText = '';
    if (typeof msg.payload === 'string') fileText = msg.payload;
    else if (msg.payload !== undefined && msg.payload !== null) fileText = String(msg.payload);

    loadedState.rows = parseFileRows(fileText, loadedState.selectedKind, loadedState.selectedFile, loadedState.selectedProtocol);
    loadedState.error = '';
    loadedState.error_en = '';
    saveJournalState(loadedState);
    return [null, null, getJournalMessage(loadedState), null, null];
}

return null;
